#include "wokwi-api.h"
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct { uint8_t r,g,b,a; } rgba_t;

typedef struct {
  buffer_t framebuffer;
  uint32_t width;
  uint32_t height;
  uart_dev_t uart;
  char rx_buffer[128];
  uint32_t rx_pos;
} chip_state_t;

/*
 * P&P Taster visual prototype.
 *
 * Keeps the known-working framebuffer/UART boundary and READY/START/RACING
 * command protocol. The old 5x7 font is replaced by a compact anti-aliased
 * DejaVu Sans Bold glyph set. The MGB and E-Type are embedded at their actual
 * on-screen size as RGB565 + alpha assets.
 *
 * This remains a visual prototype: no timing engine, detectors, PB logic,
 * race logic, or fake sensor events live here.
 */

/* ---------- Colours ---------- */
static const rgba_t BG       = {  7, 15, 25,255};
static const rgba_t PANEL    = { 12, 26, 42,255};
static const rgba_t BORDER   = { 43, 66, 87,255};
static const rgba_t POD      = { 10, 23, 36,255};
static const rgba_t PODEDGE  = { 79, 98,114,255};
static const rgba_t DORMANT  = { 56, 68, 78,255};
static const rgba_t REDLAMP  = {230, 45, 45,255};
static const rgba_t WHITE    = {238,243,248,255};
static const rgba_t MUTED    = {133,151,169,255};
static const rgba_t YELLOW   = {255,205,  0,255};
static const rgba_t GREEN    = { 89,222,139,255};
static const rgba_t BLUE     = { 32,139,255,255};
static const rgba_t RED      = {239, 62, 66,255};
static const rgba_t GAPRED   = {255,104, 94,255};

/* ---------- Low-level framebuffer ---------- */
static void pixel(chip_state_t *c,int x,int y,rgba_t col) {
  if (x<0 || y<0 || x>=(int)c->width || y>=(int)c->height) return;
  uint32_t off=((uint32_t)y*c->width+(uint32_t)x)*4;
  buffer_write(c->framebuffer,off,&col,sizeof(col));
}
static void fill_rect(chip_state_t *c,int x,int y,int w,int h,rgba_t col) {
  for(int yy=y;yy<y+h;yy++) for(int xx=x;xx<x+w;xx++) pixel(c,xx,yy,col);
}
static void line(chip_state_t *c,int x0,int y0,int x1,int y1,rgba_t col) {
  int dx=abs(x1-x0),sx=x0<x1?1:-1,dy=-abs(y1-y0),sy=y0<y1?1:-1,err=dx+dy;
  for(;;){ pixel(c,x0,y0,col); if(x0==x1&&y0==y1)break; int e2=2*err;
    if(e2>=dy){err+=dy;x0+=sx;} if(e2<=dx){err+=dx;y0+=sy;} }
}
static void circle(chip_state_t *c,int cx,int cy,int r,rgba_t col) {
  for(int y=-r;y<=r;y++) for(int x=-r;x<=r;x++)
    if(x*x+y*y<=r*r) pixel(c,cx+x,cy+y,col);
}
static rgba_t blend(rgba_t dst, rgba_t src, uint8_t alpha) {
  uint16_t ia=255-alpha; rgba_t o;
  o.r=(uint8_t)(((uint16_t)src.r*alpha+(uint16_t)dst.r*ia)/255);
  o.g=(uint8_t)(((uint16_t)src.g*alpha+(uint16_t)dst.g*ia)/255);
  o.b=(uint8_t)(((uint16_t)src.b*alpha+(uint16_t)dst.b*ia)/255);
  o.a=255; return o;
}

