static const glyph_t *find_glyph(uint32_t code) {
  for(size_t i=0;i<sizeof(GLYPHS)/sizeof(GLYPHS[0]);i++)
    if(GLYPHS[i].code==code) return &GLYPHS[i];
  return NULL;
}
static int utf8_code(const char **ps) {
  const unsigned char *s=(const unsigned char*)*ps;
  if(s[0]==0xE2 && s[1]==0x80 && s[2]==0x94){*ps+=3;return 0x2014;}
  int c=*s; (*ps)++; return c;
}
static int glyph_alpha(const glyph_t *g,int p) {
  uint8_t b=g->data[p>>1];
  return (p&1)?(b&15):(b>>4);
}
static int text_width(const char *s,int scale) {
  int w=0; const char *p=s;
  while(*p){int cp=utf8_code(&p); const glyph_t *g=find_glyph((uint32_t)cp);
    if(g) w+=(g->w+2)*scale;}
  return w? w-2*scale:0;
}
static void aa_text(chip_state_t *c,int x,int y,const char *s,int scale,rgba_t col) {
  const char *p=s;
  while(*p){
    int cp=utf8_code(&p); const glyph_t *g=find_glyph((uint32_t)cp);
    if(!g) continue;
    for(int gy=0;gy<g->h;gy++) for(int gx=0;gx<g->w;gx++){
      int a4=glyph_alpha(g,gy*g->w+gx); if(!a4)continue;
      uint8_t a=(uint8_t)(a4*17);
      for(int sy=0;sy<scale;sy++) for(int sx=0;sx<scale;sx++){
        int px=x+gx*scale+sx, py=y+gy*scale+sy;
        /* UI is opaque; approximate destination from known background/panel. */
        rgba_t dst=(py>=177 && py<=365)?PANEL:BG;
        pixel(c,px,py,blend(dst,col,a));
      }
    }
    x+=(g->w+2)*scale;
  }
}
static void aa_text_center(chip_state_t *c,int cx,int y,const char *s,int scale,rgba_t col){
  aa_text(c,cx-text_width(s,scale)/2,y,s,scale,col);
}

