static void draw_car(chip_state_t *c,int x,int y,const uint32_t *asset) {
  for(int yy=0;yy<CAR_H;yy++) for(int xx=0;xx<CAR_W;xx++){
    uint32_t v=asset[yy*CAR_W+xx]; uint8_t a=(uint8_t)(v>>16); if(!a)continue;
    uint16_t q=(uint16_t)v;
    rgba_t src={
      (uint8_t)(((q>>11)&31)*255/31),
      (uint8_t)(((q>>5)&63)*255/63),
      (uint8_t)((q&31)*255/31),255
    };
    pixel(c,x+xx,y+yy,blend(PANEL,src,a));
  }
}

/* ---------- UI ---------- */
static void draw_pod(chip_state_t *c,int active_lights,int racing){
  for(int y=0;y<=64;y++){int inset=y*38/64; line(c,130+inset,y,670-inset,y,POD);}
  line(c,130,0,168,64,PODEDGE); line(c,670,0,632,64,PODEDGE); line(c,168,64,632,64,PODEDGE);
  const int lx[5]={292,346,400,454,508};
  for(int i=0;i<5;i++){circle(c,lx[i],31,17,BORDER);
    circle(c,lx[i],31,13,(!racing && i<active_lights)?REDLAMP:DORMANT);}
}
static void draw_common(chip_state_t *c,const char *mode,const char *value,
                        const char *r1,const char *r2,int lights,int racing){
  fill_rect(c,0,0,c->width,c->height,BG);
  draw_pod(c,lights,racing);

  /* Race definition */
  aa_text_center(c,365,76,value,2,WHITE);
  aa_text(c,405,92,mode,1,YELLOW);

  /* Column headings */
  aa_text(c,52,148,"RACER",1,MUTED);
  aa_text_center(c,420,148,"LAPS",1,MUTED);
  aa_text_center(c,525,148,"LAST",1,MUTED);
  aa_text_center(c,625,148,"BEST",1,MUTED);
  aa_text_center(c,735,148,"GAP",1,MUTED);

  /* Lane panels */
  fill_rect(c,20,177,760,88,PANEL); fill_rect(c,20,177,7,88,BLUE);
  line(c,20,177,780,177,BORDER); line(c,20,265,780,265,BORDER);
  fill_rect(c,20,277,760,88,PANEL); fill_rect(c,20,277,7,88,RED);
  line(c,20,277,780,277,BORDER); line(c,20,365,780,365,BORDER);

  draw_car(c,35,182,CAR_MGB);
  draw_car(c,35,282,CAR_ETYPE);
  aa_text(c,225,190,r1,1,WHITE); aa_text(c,225,290,r2,1,WHITE);
  aa_text(c,225,225,"LANE 1",1,BLUE); aa_text(c,225,325,"LANE 2",1,RED);

  if(racing){
    aa_text_center(c,420,202,"6/10",1,WHITE);
    aa_text_center(c,525,202,"8.43",1,WHITE);
    aa_text_center(c,625,202,"8.17",1,GREEN);
    aa_text_center(c,735,202,"—",1,MUTED);
    aa_text_center(c,420,302,"5/10",1,WHITE);
    aa_text_center(c,525,302,"8.71",1,WHITE);
    aa_text_center(c,625,302,"8.29",1,GREEN);
    aa_text_center(c,735,302,"+1.24",1,GAPRED);
  } else {
    char p[20]; snprintf(p,sizeof(p),"0/%s",value);
    aa_text_center(c,420,202,p,1,WHITE);
    aa_text_center(c,420,302,p,1,WHITE);
    aa_text_center(c,525,202,"--",1,MUTED); aa_text_center(c,625,202,"--",1,MUTED);
    aa_text_center(c,735,202,"-",1,MUTED);  aa_text_center(c,525,302,"--",1,MUTED);
    aa_text_center(c,625,302,"--",1,MUTED); aa_text_center(c,735,302,"-",1,MUTED);
    if(lights==0) aa_text_center(c,400,407,"PRESS ENCODER TO START",1,YELLOW);
  }
  line(c,20,388,780,388,(rgba_t){20,36,50,255});
}

/* ---------- Command parser: protocol unchanged ---------- */
static void process_command(chip_state_t *c){
  printf("Command received: %s\n",c->rx_buffer);

  if(strncmp(c->rx_buffer,"READY|",6)==0){
    char *state=strtok(c->rx_buffer,"|"),*mode=strtok(NULL,"|"),*value=strtok(NULL,"|");
    char *r1=strtok(NULL,"|"),*r2=strtok(NULL,"|");
    if(state&&mode&&value&&r1&&r2) draw_common(c,mode,value,r1,r2,0,0);
    return;
  }
  if(strncmp(c->rx_buffer,"START|",6)==0){
    char *state=strtok(c->rx_buffer,"|"),*count=strtok(NULL,"|"),*mode=strtok(NULL,"|");
    char *value=strtok(NULL,"|"),*r1=strtok(NULL,"|"),*r2=strtok(NULL,"|");
    if(state&&count&&mode&&value&&r1&&r2){
      int n=atoi(count); if(n<0)n=0; if(n>5)n=5;
      draw_common(c,mode,value,r1,r2,n,0);
    }
    return;
  }
  if(strncmp(c->rx_buffer,"RACING|",7)==0){
    char *state=strtok(c->rx_buffer,"|"),*mode=strtok(NULL,"|"),*value=strtok(NULL,"|");
    char *r1=strtok(NULL,"|"),*r2=strtok(NULL,"|");
    if(state&&mode&&value&&r1&&r2) draw_common(c,mode,value,r1,r2,0,1);
    return;
  }
  if(strncmp(c->rx_buffer,"PAUSED|",7)==0 || strncmp(c->rx_buffer,"FINISHED|",9)==0){
    const int finished = strncmp(c->rx_buffer,"FINISHED|",9)==0;
    char *state=strtok(c->rx_buffer,"|"),*mode=strtok(NULL,"|"),*value=strtok(NULL,"|");
    char *r1=strtok(NULL,"|"),*r2=strtok(NULL,"|");
    if(state&&mode&&value&&r1&&r2){
      draw_common(c,mode,value,r1,r2,0,1);
      aa_text_center(c,400,407,finished?"RESULT":"PAUSED",1,YELLOW);
    }
    return;
  }
  if(strncmp(c->rx_buffer,"PROMPT|",7)==0){
    char *state=strtok(c->rx_buffer,"|"),*choice=strtok(NULL,"|"),*mode=strtok(NULL,"|"),*value=strtok(NULL,"|");
    char *r1=strtok(NULL,"|"),*r2=strtok(NULL,"|");
    if(state&&choice&&mode&&value&&r1&&r2){
      draw_common(c,mode,value,r1,r2,0,1);
      aa_text_center(c,400,407,choice,1,YELLOW);
    }
    return;
  }
}

/* ---------- UART receive: known-working boundary unchanged ---------- */
static void on_uart_rx_data(void *user_data,uint8_t byte){
  chip_state_t *c=(chip_state_t*)user_data;
  if(byte=='\r')return;
  if(byte=='\n'){
    c->rx_buffer[c->rx_pos]='\0';
    process_command(c);
    c->rx_pos=0;
    return;
  }
  if(c->rx_pos<sizeof(c->rx_buffer)-1) c->rx_buffer[c->rx_pos++]=byte;
}

/* ---------- Initialisation: known-working boundary unchanged ---------- */
void chip_init(void){
  chip_state_t *c=malloc(sizeof(chip_state_t));
  c->rx_pos=0;
  c->framebuffer=framebuffer_init(&c->width,&c->height);
  printf("Framebuffer: width=%lu, height=%lu\n",
         (unsigned long)c->width,(unsigned long)c->height);

  const uart_config_t uart_config={
    .tx=pin_init("OUT",INPUT_PULLUP),
    .rx=pin_init("IN",INPUT),
    .baud_rate=115200,
    .rx_data=on_uart_rx_data,
    .write_done=NULL,
    .user_data=c,
  };
  c->uart=uart_init(&uart_config);
  printf("P&P display UART ready\n");
}
